import torch


def _rgb_to_grayscale(imgs: torch.Tensor) -> torch.Tensor:
    weights = imgs.new_tensor([0.2989, 0.5870, 0.1140]).view(1, 3, 1, 1)
    return (imgs * weights).sum(dim=1, keepdim=True)


def _blend(img1: torch.Tensor, img2: torch.Tensor, factor: torch.Tensor) -> torch.Tensor:
    return img2 + factor * (img1 - img2)


def _adjust_brightness(imgs: torch.Tensor, factor: torch.Tensor) -> torch.Tensor:
    return imgs * factor


def _adjust_contrast(imgs: torch.Tensor, factor: torch.Tensor) -> torch.Tensor:
    gray = _rgb_to_grayscale(imgs)
    mean = gray.mean(dim=(2, 3), keepdim=True)
    return _blend(imgs, mean, factor)


def _adjust_saturation(imgs: torch.Tensor, factor: torch.Tensor) -> torch.Tensor:
    gray = _rgb_to_grayscale(imgs)
    return _blend(imgs, gray, factor)


def aug_code(batch_x, batch_y):
    if batch_x.ndim != 4 or batch_x.shape[1:] != (3, 224, 224):
        raise ValueError("batch_x must have shape [B, 3, 224, 224]")

    x = batch_x.to(torch.float32)
    b = x.shape[0]
    device = x.device

    brightness = torch.empty(b, 1, 1, 1, device=device).uniform_(0.8, 1.2)
    contrast = torch.empty(b, 1, 1, 1, device=device).uniform_(0.8, 1.2)
    saturation = torch.empty(b, 1, 1, 1, device=device).uniform_(0.8, 1.2)

    order = torch.stack([torch.randperm(3, device=device) for _ in range(b)], dim=0)
    out = x.clone()

    for i in range(b):
        img = out[i:i + 1]
        for op_idx in order[i].tolist():
            if op_idx == 0:
                img = _adjust_brightness(img, brightness[i:i + 1])
            elif op_idx == 1:
                img = _adjust_contrast(img, contrast[i:i + 1])
            else:
                img = _adjust_saturation(img, saturation[i:i + 1])
        out[i:i + 1] = img

    out = out.clamp_(0.0, 255.0).round_().to(batch_x.dtype)
    return out, batch_y


