import torch


def _apply_random_horizontal_flip(batch_x: torch.Tensor, p: float) -> torch.Tensor:
    if p <= 0.0:
        return batch_x
    flip_mask = torch.rand(batch_x.shape[0], device=batch_x.device) < p
    if flip_mask.any():
        batch_x = batch_x.clone()
        batch_x[flip_mask] = torch.flip(batch_x[flip_mask], dims=[3])
    return batch_x


def _rgb_to_grayscale(imgs: torch.Tensor) -> torch.Tensor:
    weights = imgs.new_tensor([0.2989, 0.5870, 0.1140]).view(1, 3, 1, 1)
    gray = (imgs * weights).sum(dim=1, keepdim=True)
    return gray.expand_as(imgs)


def _apply_color_jitter(
    batch_x: torch.Tensor,
    brightness: float,
    contrast: float,
    saturation: float,
) -> torch.Tensor:
    imgs = batch_x.to(torch.float32)
    b = imgs.shape[0]

    if brightness > 0.0:
        factors = torch.empty(b, 1, 1, 1, device=imgs.device).uniform_(max(0.0, 1.0 - brightness), 1.0 + brightness)
        imgs = imgs * factors

    if contrast > 0.0:
        factors = torch.empty(b, 1, 1, 1, device=imgs.device).uniform_(max(0.0, 1.0 - contrast), 1.0 + contrast)
        means = imgs.mean(dim=(2, 3), keepdim=True)
        imgs = (imgs - means) * factors + means

    if saturation > 0.0:
        factors = torch.empty(b, 1, 1, 1, device=imgs.device).uniform_(max(0.0, 1.0 - saturation), 1.0 + saturation)
        gray = _rgb_to_grayscale(imgs)
        imgs = (imgs - gray) * factors + gray

    return imgs.clamp_(0.0, 255.0).to(batch_x.dtype)


def aug_code(batch_x, batch_y):
    batch_x = _apply_random_horizontal_flip(batch_x, p=0.5)
    batch_x = _apply_color_jitter(
        batch_x,
        brightness=0.2,
        contrast=0.2,
        saturation=0.2,
    )
    return batch_x, batch_y


