def aug_code(batch_x, batch_y):
    if torch.rand((), device=batch_x.device) < 0.3:
        x = batch_x.to(torch.float32)
        noise = torch.randn_like(x) * (0.01 * 255.0)
        batch_x_aug = torch.clamp(x + noise, 0.0, 255.0)
    else:
        batch_x_aug = batch_x
    batch_y_aug = batch_y
    return batch_x_aug, batch_y_aug

import torch


def _sample_patch_size(height, width, max_area_pixels, device):
    max_area_pixels = max(1, min(int(max_area_pixels), height * width))
    for _ in range(32):
        patch_h = int(torch.randint(1, height + 1, (1,), device=device).item())
        patch_w = int(torch.randint(1, width + 1, (1,), device=device).item())
        if patch_h * patch_w <= max_area_pixels:
            return patch_h, patch_w
    target_area = int(torch.randint(1, max_area_pixels + 1, (1,), device=device).item())
    patch_h = max(1, min(height, int(target_area ** 0.5)))
    patch_w = max(1, min(width, target_area // patch_h))
    while patch_h * patch_w > max_area_pixels and patch_w > 1:
        patch_w -= 1
    return patch_h, max(1, patch_w)


def _random_partner_indices(batch_size, device):
    if batch_size < 2:
        return torch.arange(batch_size, device=device)
    identity = torch.arange(batch_size, device=device)
    for _ in range(16):
        partner_idx = torch.randperm(batch_size, device=device)
        if not torch.any(partner_idx == identity):
            return partner_idx
    return torch.roll(identity, shifts=1)


def aug_code(batch_x, batch_y):
    batch_x_aug = batch_x.clone()
    batch_y_aug = batch_y

    batch_size, _, height, width = batch_x.shape
    if batch_size < 2:
        return batch_x_aug, batch_y_aug

    device = batch_x.device
    partner_idx = _random_partner_indices(batch_size, device)
    apply_mask = torch.rand(batch_size, device=device) < 0.5
    max_area_pixels = int(0.15 * height * width)

    for i in torch.nonzero(apply_mask, as_tuple=False).flatten().tolist():
        j = int(partner_idx[i].item())
        alpha = float(torch.empty(1, device=device).uniform_(0.3, 0.7).item())
        patch_h, patch_w = _sample_patch_size(height, width, max_area_pixels, device)
        top = int(torch.randint(0, height - patch_h + 1, (1,), device=device).item())
        left = int(torch.randint(0, width - patch_w + 1, (1,), device=device).item())

        base_patch = batch_x[i, :, top:top + patch_h, left:left + patch_w].to(torch.float32)
        other_patch = batch_x[j, :, top:top + patch_h, left:left + patch_w].to(torch.float32)
        blended_patch = torch.round(base_patch * (1.0 - alpha) + other_patch * alpha).clamp(0, 255)
        batch_x_aug[i, :, top:top + patch_h, left:left + patch_w] = blended_patch.to(batch_x.dtype)

    return batch_x_aug, batch_y_aug

