import torch


def _posterize_uint8(x: torch.Tensor, bits: int) -> torch.Tensor:
    if bits >= 8:
        return x
    if bits <= 0:
        return torch.zeros_like(x)
    mask = (0xFF << (8 - bits)) & 0xFF
    return x & mask


def aug_code(batch_x, batch_y):
    if random.random() >= 0.3:
