import torch.nn.functional as F


def _horizontal_flip(batch_x: torch.Tensor) -> torch.Tensor:
    return torch.flip(batch_x, dims=(-1,))


def _random_affine_translate(batch_x: torch.Tensor, max_fraction: float = 0.1) -> torch.Tensor:
    b, c, h, w = batch_x.shape
    max_dx = int(round(w * max_fraction))
    max_dy = int(round(h * max_fraction))
    if max_dx == 0 and max_dy == 0:
        return batch_x

    out = batch_x.clone()
    dx = torch.randint(-max_dx, max_dx + 1, (b,), device=batch_x.device) if max_dx > 0 else torch.zeros(b, dtype=torch.long, device=batch_x.device)
    dy = torch.randint(-max_dy, max_dy + 1, (b,), device=batch_x.device) if max_dy > 0 else torch.zeros(b, dtype=torch.long, device=batch_x.device)

    for i in range(b):
        sx = int(dx[i].item())
        sy = int(dy[i].item())
        img = torch.roll(batch_x[i], shifts=(sy, sx), dims=(-2, -1))

        if sy > 0:
            img[:, :sy, :] = 0
        elif sy < 0:
            img[:, sy:, :] = 0

        if sx > 0:
            img[:, :, :sx] = 0
        elif sx < 0:
            img[:, :, sx:] = 0

        out[i] = img

    return out


def aug_code(batch_x, batch_y):
    ops = (_horizontal_flip, _random_affine_translate)
    num_ops = int(torch.randint(1, 3, (1,)).item())
    selected = torch.randperm(len(ops))[:num_ops].tolist()

    batch_x_aug = batch_x
    for idx in selected:
        if torch.rand(()) < 0.8:
            if idx == 0:
                batch_x_aug = ops[idx](batch_x_aug)
            else:
                batch_x_aug = ops[idx](batch_x_aug, max_fraction=0.1)

    batch_y_aug = batch_y
    return batch_x_aug, batch_y_aug

