def _translate_batch(x, tx, ty):
    if tx == 0 and ty == 0:
        return x
    b, c, h, w = x.shape
    out = torch.zeros_like(x)

    src_x0 = max(0, -tx)
    src_x1 = min(w, w - tx) if tx >= 0 else w
    dst_x0 = max(0, tx)
    dst_x1 = dst_x0 + (src_x1 - src_x0)

    src_y0 = max(0, -ty)
    src_y1 = min(h, h - ty) if ty >= 0 else h
    dst_y0 = max(0, ty)
    dst_y1 = dst_y0 + (src_y1 - src_y0)

    if src_x1 > src_x0 and src_y1 > src_y0:
        out[:, :, dst_y0:dst_y1, dst_x0:dst_x1] = x[:, :, src_y0:src_y1, src_x0:src_x1]
    return out


def _random_horizontal_flip_batch(x):
    return torch.flip(x, dims=(-1,))


def _random_affine_translate_batch(x, translate_max_fraction=0.1):
    h, w = x.shape[-2:]
    max_dx = int(round(w * translate_max_fraction))
    max_dy = int(round(h * translate_max_fraction))
    tx = random.randint(-max_dx, max_dx)
    ty = random.randint(-max_dy, max_dy)
    return _translate_batch(x, tx, ty)


def _random_solarize_batch(x, threshold=0.5):
    thr = threshold * 255.0
    max_val = 255.0 if x.is_floating_point() else 255
    return torch.where(x >= thr, max_val - x, x)


def aug_code(batch_x, batch_y):
    x = batch_x

    ops = [_random_horizontal_flip_batch, _random_affine_translate_batch]
    sampled_ops = random.sample(ops, k=2)
    for op in sampled_ops:
        if random.random() < 0.8:
            x = op(x)

    if random.random() < 0.3:
        x = _random_solarize_batch(x, threshold=0.5)

    return x, batch_y

