def _apply_affine(batch_x, theta):
    x = batch_x.float()
    grid = F.affine_grid(theta, size=x.shape, align_corners=False)
    x = F.grid_sample(x, grid, mode="bilinear", padding_mode="zeros", align_corners=False)
    return x.clamp(0, 255).round().to(batch_x.dtype)


def _random_translate(batch_x, max_fraction):
    b = batch_x.shape[0]
    theta = torch.zeros((b, 2, 3), device=batch_x.device, dtype=torch.float32)
    theta[:, 0, 0] = 1.0
    theta[:, 1, 1] = 1.0
    theta[:, 0, 2] = torch.empty(b, device=batch_x.device).uniform_(-2.0 * max_fraction, 2.0 * max_fraction)
    theta[:, 1, 2] = torch.empty(b, device=batch_x.device).uniform_(-2.0 * max_fraction, 2.0 * max_fraction)
    return _apply_affine(batch_x, theta)


def _random_scale(batch_x, min_scale, max_scale):
    b = batch_x.shape[0]
    scales = torch.empty(b, device=batch_x.device).uniform_(min_scale, max_scale)
    inv_scales = 1.0 / scales
    theta = torch.zeros((b, 2, 3), device=batch_x.device, dtype=torch.float32)
    theta[:, 0, 0] = inv_scales
    theta[:, 1, 1] = inv_scales
    return _apply_affine(batch_x, theta)


def aug_code(batch_x, batch_y):
    batch_x_aug = batch_x
    selected_ops = torch.randperm(3)[:2].tolist()

    for op_idx in selected_ops:
        if torch.rand(()) < 0.7:
            if op_idx == 0:
                batch_x_aug = torch.flip(batch_x_aug, dims=(-1,))
            elif op_idx == 1:
                batch_x_aug = _random_translate(batch_x_aug, 0.1)
            else:
                batch_x_aug = _random_scale(batch_x_aug, 0.85, 1.15)

    batch_y_aug = batch_y
    return batch_x_aug, batch_y_aug

