import torch.nn.functional as F


def _apply_affine(batch_x, scales=None, tx=None, ty=None):
    b, c, h, w = batch_x.shape
    device = batch_x.device
    dtype = torch.float32

    if scales is None:
        scales = torch.ones(b, device=device, dtype=dtype)
    if tx is None:
        tx = torch.zeros(b, device=device, dtype=dtype)
    if ty is None:
        ty = torch.zeros(b, device=device, dtype=dtype)

    theta = torch.zeros(b, 2, 3, device=device, dtype=dtype)
    inv_scales = 1.0 / scales
    theta[:, 0, 0] = inv_scales
    theta[:, 1, 1] = inv_scales
    theta[:, 0, 2] = tx
    theta[:, 1, 2] = ty

    x = batch_x.to(dtype)
    grid = F.affine_grid(theta, size=x.shape, align_corners=False)
    x = F.grid_sample(x, grid, mode="bilinear", padding_mode="zeros", align_corners=False)
    return x.clamp(0, 255).round().to(batch_x.dtype)


def _random_horizontal_flip(batch_x):
    mask = torch.rand(batch_x.shape[0], device=batch_x.device) < 0.5
    if mask.any():
        batch_x = batch_x.clone()
        batch_x[mask] = torch.flip(batch_x[mask], dims=[3])
    return batch_x


def _random_affine_translate(batch_x, translate_fraction=0.1):
    b = batch_x.shape[0]
    tx = (torch.rand(b, device=batch_x.device) * 2.0 - 1.0) * (2.0 * translate_fraction)
    ty = (torch.rand(b, device=batch_x.device) * 2.0 - 1.0) * (2.0 * translate_fraction)
    return _apply_affine(batch_x, tx=tx, ty=ty)


def _random_affine_scale(batch_x, min_scale=0.85, max_scale=1.15):
    b = batch_x.shape[0]
    scales = torch.empty(b, device=batch_x.device).uniform_(min_scale, max_scale)
    return _apply_affine(batch_x, scales=scales)


def _random_solarize(batch_x, threshold=0.4):
    thr = threshold * 255.0
    if batch_x.is_floating_point():
        max_val = 255.0
    else:
        max_val = 255
    return torch.where(batch_x >= thr, max_val - batch_x, batch_x)


def aug_code(batch_x, batch_y):
    ops = [
        _random_horizontal_flip,
        lambda x: _random_affine_translate(x, translate_fraction=0.1),
        lambda x: _random_affine_scale(x, min_scale=0.85, max_scale=1.15),
        lambda x: _random_solarize(x, threshold=0.4),
    ]

    batch_x_aug = batch_x
    for op in random.sample(ops, 2):
        if random.random() < 0.6:
            batch_x_aug = op(batch_x_aug)

    batch_y_aug = batch_y
    return batch_x_aug, batch_y_aug

import torch


def _rgb_to_grayscale(x: torch.Tensor) -> torch.Tensor:
    w = x.new_tensor([0.2989, 0.5870, 0.1140]).view(1, 3, 1, 1)
    return (x * w).sum(dim=1, keepdim=True)


def aug_code(batch_x, batch_y):
    if not isinstance(batch_x, torch.Tensor) or not isinstance(batch_y, torch.Tensor):
        raise TypeError("batch_x and batch_y must be torch.Tensor")

    if torch.rand((), device=batch_x.device) >= 0.5:
        return batch_x, batch_y

    x = batch_x.to(torch.float32)
    b = x.shape[0]
    contrast = torch.empty(b, 1, 1, 1, device=x.device).uniform_(0.4, 1.6)
    saturation = torch.empty(b, 1, 1, 1, device=x.device).uniform_(0.4, 1.6)

    gray = _rgb_to_grayscale(x)
    x = gray + saturation * (x - gray)

    mean = x.mean(dim=(1, 2, 3), keepdim=True)
    x = mean + contrast * (x - mean)

    if batch_x.dtype == torch.uint8:
        x = x.clamp(0, 255).round().to(torch.uint8)
    else:
        x = x.clamp(0, 255).to(batch_x.dtype)

    return x, batch_y

import torch


def _equalize_channel(channel: torch.Tensor) -> torch.Tensor:
    x_u8 = channel.clamp(0, 255).round().to(torch.uint8)
    hist = torch.bincount(x_u8.reshape(-1).to(torch.int64), minlength=256)
    nonzero = hist > 0
    if not torch.any(nonzero):
        return channel
    cdf = hist.cumsum(0)
    cdf_min = cdf[nonzero][0]
    total = channel.numel()
    denom = total - cdf_min
    if denom <= 0:
        return channel
    lut = ((cdf - cdf_min).clamp(min=0).to(torch.float32) * 255.0 / float(denom)).round().clamp(0, 255).to(torch.uint8)
    eq_u8 = lut[x_u8.to(torch.int64)]
    if channel.dtype == torch.uint8:
        return eq_u8
    return eq_u8.to(channel.dtype)


def _equalize_image(img: torch.Tensor) -> torch.Tensor:
    out = img.clone()
    for c in range(out.shape[0]):
        out[c] = _equalize_channel(out[c])
    return out


def aug_code(batch_x, batch_y):
    p = 0.1
    if batch_x.ndim != 4:
        raise ValueError('batch_x must have shape [B, C, H, W]')

    batch_x_aug = batch_x
    apply_mask = torch.rand(batch_x.shape[0], device=batch_x.device) < p
    if torch.any(apply_mask):
        batch_x_aug = batch_x.clone()
        indices = torch.nonzero(apply_mask, as_tuple=False).flatten()
        for i in indices.tolist():
            batch_x_aug[i] = _equalize_image(batch_x_aug[i])

    batch_y_aug = batch_y
    return batch_x_aug, batch_y_aug
